import{_ as t,o,c as n,ah as r}from"./chunks/framework.ChH6X6u6.js";const u=JSON.parse('{"title":"Retention","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/gestion-documentaire/conservation.md","filePath":"src/en/guide/gestion-documentaire/conservation.md"}'),a={name:"en/guide/gestion-documentaire/conservation.md"};function s(i,e,d,c,h,l){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="retention" tabindex="-1">Retention <a class="header-anchor" href="#retention" aria-label="Permalink to &quot;Retention&quot;">​</a></h1><p>Each document type has a <strong>retention period</strong>, set in the <a href="/era-guide/en/guide/gestion-documentaire/types-de-documents.html">Document types</a>. Once that period is over, ERA <strong>archives</strong> the document on its own. It <strong>never destroys</strong> it on its own: destruction is proposed, then approved by an administrator.</p><h2 id="when-a-document-is-archived" tabindex="-1">When a document is archived <a class="header-anchor" href="#when-a-document-is-archived" aria-label="Permalink to &quot;When a document is archived&quot;">​</a></h2><p>The period is counted from the <strong>date of the document</strong> (the one it carries) or, failing that, the day it was filed. For example, an enrolment file dated 2 September 2019 and kept 5 years is archived from 2 September 2024.</p><p>ERA checks every night for documents to archive. Only <strong>validated</strong> or <strong>rejected</strong> documents are archived: a document still waiting to be checked stays where it is. A type with no retention period keeps its documents without limit.</p><p>An archived document stays in its file, with the <strong>Archived</strong> label: it opens as before. It can no longer be removed with the <strong>Delete</strong> button, though, even by an administrator: it leaves the file only by an approved destruction.</p><h2 id="the-retention-screen" tabindex="-1">The Retention screen <a class="header-anchor" href="#the-retention-screen" aria-label="Permalink to &quot;The Retention screen&quot;">​</a></h2><p>The <strong>Documents</strong> → <strong>Retention</strong> screen is for an administrator and the document manager. It shows:</p><ul><li>how many documents will be archived in the <strong>next 90 days</strong>;</li><li>the <strong>Destruction proposed</strong> list: the documents someone has proposed to destroy, with their name and the date;</li><li>the <strong>Archived</strong> list: archived documents nobody has proposed to destroy yet.</li></ul><p>Each row shows the type and the person concerned, and offers <strong>Open</strong> to read the document again before deciding.</p><h2 id="propose-a-destruction" tabindex="-1">Propose a destruction <a class="header-anchor" href="#propose-a-destruction" aria-label="Permalink to &quot;Propose a destruction&quot;">​</a></h2><ol><li>Under <strong>Archived</strong>, tick the documents to destroy, or <strong>Select all</strong>.</li><li>Click <strong>Propose destruction</strong>.</li></ol><p>The documents move to <strong>Destruction proposed</strong>, with a label of the same name in their file. The administrators&#39; dashboard shows how many destructions are waiting for their approval.</p><h2 id="approve-or-refuse-a-destruction" tabindex="-1">Approve or refuse a destruction <a class="header-anchor" href="#approve-or-refuse-a-destruction" aria-label="Permalink to &quot;Approve or refuse a destruction&quot;">​</a></h2><p>Only an administrator approves a destruction.</p><ol><li>Under <strong>Destruction proposed</strong>, tick the documents.</li><li>Click <strong>Destroy</strong>, then confirm. The documents and their files are deleted for good.</li></ol><p>To refuse, click <strong>Keep</strong>: the documents stay archived, and can be proposed again later. The document manager can also withdraw a proposal of their own this way.</p><p>Every step (archiving, proposal, destruction, refusal) is recorded in the <a href="/era-guide/en/guide/admin/demo-et-journal.html">activity log</a>, with the person who took it.</p>',18)])])}const m=t(a,[["render",s]]);export{u as __pageData,m as default};
